head.script:
// https://inswave01.atlassian.net/browse/WAEA-955



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setGridHeight]<br/>GridView 컴포넌트의 높이(Height)를 설정합니다.",
    "validation" : [
        "height(필수) 파라미터로 GridView 컴포넌트의 높이(Height)를 픽셀(px)로 설정합니다.",
        "setGridHeight() 실행 시 visibleRowNum 속성은 무시되고 GridView 의 높이가 변경됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - visibleRowNum="6" 로 초기 높이를 6행 기준 자동 설정(약 280px). setGridHeight 가 이를 무시하고 높이 변경 (@spec2 전제)
//  - 초기 높이가 곧 최대치이므로 par_height 는 모두 그보다 작은 값(축소 경로)으로 구성 -> setGridHeight 를 한 번만 호출해도 정확 반영
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 바인딩 DataList 생성 (col1~col4, 10행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);
    // scwin.fillData();

    // 테스트 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 그리드 visibleRowNum=6 (초기 높이 약 280px 로 표시)\n[절차] par_height 값(100 / 150 / 200 / 250) 선택 후 (setGridHeight) 클릭\n[확인] 그리드 offsetHeight 가 설정 px 로 적용 (visibleRowNum 무시하고 높이 변경)\n[참고] 더 큰 값 테스트 시 (Target 재생성) 으로 초기 높이 복원 후 선택"', '', 'label1');

    // target 생성 (visibleRowNum=6, 초기 높이가 최대치)
    await scwin.createGridView();
}



// // 그리드 데이터 (10행 : visibleRowNum(6)보다 많아 세로 스크롤 존재)
// scwin.fillData = function () {
//     let rows = [];
//     for (var i = 1; i <= 10; i++) {
//         rows.push({ col1: "A" + i, col2: "B" + i, col3: "C" + i, col4: "D" + i });
//     }
//     dlt_bind.setJSON(rows, false);
// }



// gridView 동적 생성 (세로 넘침 + visibleRowNum=6)
scwin.createGridView = async function () {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' checkAllType="false" id="" dataList="data:dlt_bind" visibleRowNum="6" style="width:500px;height:280px;">';
    s += '<w2:caption style="" id="caption1" value="setGridHeight 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="125" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="125" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="125" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="125" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="125" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="125" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="125" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="125" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// setGridHeight 호출 : par_height(필수) 값을 그리드 높이(px)로 설정 후 적용값 확인
//  - 확인 : 그리드 컨테이너 offsetHeight 가 설정한 px 로 적용 (getGridHeight 미제공 -> DOM 측정, visibleRowNum 무시)
//  - par_height 값은 모두 초기 높이(최대치)보다 작으므로 축소 경로가 되어 setGridHeight 를 한 번만 호출해도 설정값이 정확히 반영된다.
scwin.btn_setGridHeight_onclick = function () {
    // let bottom = wf_body_bottom.getObj("scwin");
    // bottom.btn_clear_onclick();

    let vHeight = parseInt(par_height.getValue());
    let gridEl = document.querySelector("[id$='target1']");

    // 메소드 실행 : 목표 높이로 설정
    target1.setGridHeight(vHeight);

    setTimeout(function () {
        // 확인 : 그리드 컨테이너 실제 높이
        let afterHeight = gridEl ? gridEl.offsetHeight : 0;
        wf_body_bottom.getObj("scwin").setReturnValue("[설정값 height=" + vHeight + "px] 그리드 offsetHeight=" + afterHeight + "px (visibleRowNum=6 무시하고 높이 변경)");
    }, 450);
}
